<script setup lang="ts">
import { ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { DataAnalysis, ArrowRight, CircleCheck } from '@element-plus/icons-vue'
import { useSession } from '../stores/session'
const account=ref('accountant'),password=ref('demo123'),busy=ref(false),error=ref(''),session=useSession(),route=useRoute(),router=useRouter()
async function submit(){busy.value=true;error.value='';try{await session.login(account.value,password.value);const redirect=String(route.query.redirect||'/dashboard');await router.replace(redirect.startsWith('/')&&!redirect.startsWith('//')&&redirect!=='/login'?redirect:'/dashboard')}catch(e){error.value=e instanceof Error?e.message:'登录失败'}finally{busy.value=false}}
</script>
